sys_script_include.script:
var TrainingUtils = Class.create();
TrainingUtils.prototype = {
    initialize: function() {},

    getInstructorUser: function() {
        var grRole = new GlideRecord('sys_user_has_role');
        grRole.addEncodedQuery('role.name=x_1543710_traini_0.instructor^state=active');
        grRole.query();

        var instructorUser = [];

        while (grRole.next()) {
            instructorUser.push(grRole.getValue('user'))
        }
        return 'sys_idIN' + instructorUser;
    },

    uniqueRegistration: function() {
        var coursesNotToBeShown = [];
        var grRegistration = new GlideRecord('x_1543710_traini_0_registration');
        grRegistration.addEncodedQuery('opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe');
        grRegistration.query();

        while (grRegistration.next()) {
            coursesNotToBeShown.push(grRegistration.agenda.sys_id.toString());
        }

        var filteredAgenda = [];
        var grAgenda = new GlideRecord('x_1543710_traini_0_agenda');
        grAgenda.addEncodedQuery('state=2^instructor!=' + gs.getUserID().toString());
        // grAgenda.addQuery('state', '2'); 
        // grAgenda.addQuery('instructor','!=', gs.getUserID().toString());
        grAgenda.query();

        while (grAgenda.next()) {
            if (coursesNotToBeShown.indexOf(grAgenda.getUniqueValue()) == -1) {
                filteredAgenda.push("sys_id=" + grAgenda.getUniqueValue().toString() + "^OR");
            }
        }

        if (filteredAgenda.join('').slice(0, -3) == '') {
            return "instructor=c8bcbe5d39";
        }

        return filteredAgenda.join('').slice(0, -3);
    },

    type: 'TrainingUtils'
};
